/*
 * A332383  a(n) is the X-coordinate of the n-th point of the dragon curve.
 *          Sequence A332384 gives Y-coordinates.
 * https://oeis.org/A332383
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  sign, look, base
 * Formula:   a(n) = X-coordinate of the dragon curve after n steps. The
 *            sequence is generated by simulating the walk using the regular
 *            paperfolding turn sequence. For each step k (1‑based) the
 *            direction change is left if ((k & -k) << 1) & k == 0 right
 *            otherwise
 * Range:     i8 n <= 8192, i16 n <= 8192, i32 n <= 8192, i64 n <= 8192,
 *            i128 n <= 8192, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    seq_t x = 0;
    seq_t y = 0;
    idx_t dir = 0;          /* 0= east, 1= north, 2= west, 3= south */

    for (idx_t k = 1; k <= n; ++k) {
        /* move one step forward */
        switch (dir) {
        case 0: ++x; break;
        case 1: ++y; break;
        case 2: --x; break;
        case 3: --y; break;
        }

        if (k == n) break;   /* no turn after the last step */

        /* determine the next turn using the paperfolding rule */
        idx_t t = k & -k;     /* lowest set bit of k */
        if (((t << 1) & k) == 0)
            dir = (dir + 1) & 3;   /* left turn */
        else
            dir = (dir + 3) & 3;   /* right turn */
    }

    return x;
}
